dashboard.definition:
{
    "title": "Prompt Injection Detection",
    "description": "Detection of adversarial prompt injection attacks targeting AI models. Every count is distinct prompts: a prompt flagged by more than one detector (AI Defense, the ML model, the GenAI judge) counts once.",
    "inputs": {
        "input_model": {
            "dataSources": {
                "primary": "ds_model_filter"
            },
            "options": {
                "defaultValue": "*",
                "items": [
                    {
                        "label": "All Models",
                        "value": "*"
                    }
                ],
                "token": "model_filter"
            },
            "title": "Model ID",
            "type": "input.dropdown"
        },
        "input_service": {
            "dataSources": {
                "primary": "ds_service_filter"
            },
            "options": {
                "defaultValue": "*",
                "items": [
                    {
                        "label": "All Apps",
                        "value": "*"
                    }
                ],
                "token": "service_filter"
            },
            "title": "App Name",
            "type": "input.dropdown"
        },
        "input_time": {
            "options": {
                "defaultValue": "-24h@h,now",
                "token": "time"
            },
            "title": "Time Range",
            "type": "input.timerange"
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "-24h@h",
                        "latest": "now"
                    }
                }
            }
        }
    },
    "visualizations": {
        "viz_header_prompt_injection": {
            "options": {
                "fontColor": "#ffffff",
                "markdown": "## Prompt Injection Detection"
            },
            "type": "splunk.markdown"
        },
        "viz_total_scanned": {
            "dataSources": {
                "primary": "ds_total_scanned"
            },
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#53a051",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "title": "Total Scanned",
            "type": "splunk.singlevalue"
        },
        "viz_injections_detected": {
            "dataSources": {
                "primary": "ds_injections_detected"
            },
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
                "majorColorEditorConfig": [
                    {
                        "to": 1,
                        "value": "#53a051"
                    },
                    {
                        "from": 1,
                        "to": 10,
                        "value": "#f8be34"
                    },
                    {
                        "from": 10,
                        "value": "#dc4e41"
                    }
                ],
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "title": "Injections Detected",
            "type": "splunk.singlevalue"
        },
        "viz_critical_severity": {
            "dataSources": {
                "primary": "ds_critical_severity"
            },
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
                "majorColorEditorConfig": [
                    {
                        "to": 1,
                        "value": "#53a051"
                    },
                    {
                        "from": 1,
                        "value": "#dc4e41"
                    }
                ],
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "title": "Critical Severity",
            "type": "splunk.singlevalue"
        },
        "viz_high_severity": {
            "dataSources": {
                "primary": "ds_high_severity"
            },
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
                "majorColorEditorConfig": [
                    {
                        "to": 1,
                        "value": "#53a051"
                    },
                    {
                        "from": 1,
                        "to": 5,
                        "value": "#f8be34"
                    },
                    {
                        "from": 5,
                        "value": "#dc4e41"
                    }
                ],
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "title": "High Severity",
            "type": "splunk.singlevalue"
        },
        "viz_detection_rate": {
            "dataSources": {
                "primary": "ds_detection_rate"
            },
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
                "majorColorEditorConfig": [
                    {
                        "to": 2,
                        "value": "#53a051"
                    },
                    {
                        "from": 2,
                        "to": 5,
                        "value": "#f8be34"
                    },
                    {
                        "from": 5,
                        "value": "#dc4e41"
                    }
                ],
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "unit": "%",
                "unitPosition": "after"
            },
            "title": "Detection Rate",
            "type": "splunk.singlevalue"
        },
        "viz_detection_trend": {
            "dataSources": {
                "primary": "ds_detection_trend"
            },
            "options": {
                "legendDisplay": "bottom",
                "seriesColors": [
                    "#dc4e41",
                    "#53a051"
                ],
                "xAxisTitleText": "Time",
                "yAxisTitleText": "Count"
            },
            "title": "Detection Trend",
            "type": "splunk.line"
        },
        "viz_technique_distribution": {
            "dataSources": {
                "primary": "ds_technique_distribution"
            },
            "options": {
                "seriesColors": [
                    "#dc4e41",
                    "#f1813f",
                    "#f8be34",
                    "#6ab7c7",
                    "#a2cc3e",
                    "#5cc05c"
                ],
                "xAxisTitleText": "Count",
                "yAxisTitleText": "Technique"
            },
            "title": "Injections by Technique",
            "description": "A prompt can count under several techniques. AI Defense entries are the guardrail rules that fired on the prompt.",
            "type": "splunk.bar"
        },
        "viz_severity_distribution": {
            "dataSources": {
                "primary": "ds_severity_distribution"
            },
            "options": {
                "labelDisplay": "valuesAndPercentage",
                "seriesColorsByValue": {
                    "critical": "#9c1c1c",
                    "high": "#dc4e41",
                    "medium": "#f8be34",
                    "low": "#53a051",
                    "none": "#6ab7c7"
                },
                "showDonutHole": true
            },
            "title": "Severity Distribution",
            "description": "Highest severity any detector gave the prompt. An AI Defense block counts as high.",
            "type": "splunk.pie"
        },
        "viz_confidence_distribution": {
            "dataSources": {
                "primary": "ds_confidence_distribution"
            },
            "options": {
                "labelDisplay": "valuesAndPercentage",
                "seriesColorsByValue": {
                    "very_high": "#9c1c1c",
                    "high": "#dc4e41",
                    "medium": "#f8be34",
                    "low": "#53a051",
                    "very_low": "#6ab7c7"
                },
                "showDonutHole": true
            },
            "title": "Confidence Distribution",
            "description": "ML model and GenAI judge scores only. An AI Defense block carries no confidence score.",
            "type": "splunk.pie"
        },
        "viz_top_sources": {
            "dataSources": {
                "primary": "ds_top_sources"
            },
            "options": {
                "count": 10
            },
            "title": "Top Injection Sources",
            "type": "splunk.table"
        },
        "viz_recent_detections": {
            "context": {
                "SeverityColumnFormatEditorConfig": {},
                "SeverityRowBackgroundColorConfig": [
                    {
                        "match": "critical",
                        "value": "#9c1c1c"
                    },
                    {
                        "match": "high",
                        "value": "#DC4E41"
                    },
                    {
                        "match": "medium",
                        "value": "#F8BE34"
                    }
                ]
            },
            "dataSources": {
                "primary": "ds_recent_detections"
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToSearch",
                    "options": {
                        "search": "index=gen_ai_log gen_ai.request.id=\"$row.Request_ID.value$\"",
                        "earliest": "$time.earliest$",
                        "latest": "$time.latest$",
                        "openInNewTab": true
                    }
                }
            ],
            "options": {
                "columnFormat": {
                    "Severity": {
                        "data": "> table | seriesByName('Severity') | formatByType(SeverityColumnFormatEditorConfig)",
                        "rowBackgroundColors": "> table | seriesByName('Severity') | matchValue(SeverityRowBackgroundColorConfig)"
                    }
                },
                "count": 25,
                "drilldown": "row"
            },
            "title": "Recent Detections",
            "type": "splunk.table"
        }
    },
    "dataSources": {
        "ds_model_filter": {
            "options": {
                "query": "index=gen_ai_log | stats count by gen_ai.request.model | fields gen_ai.request.model",
                "queryParameters": {
                    "earliest": "-7d@d",
                    "latest": "now"
                }
            },
            "type": "ds.search"
        },
        "ds_service_filter": {
            "options": {
                "query": "index=gen_ai_log | stats count by gen_ai.app.name | fields gen_ai.app.name",
                "queryParameters": {
                    "earliest": "-7d@d",
                    "latest": "now"
                }
            },
            "type": "ds.search"
        },
        "ds_pi_base": {
            "options": {
                "query": "index=gen_ai_log gen_ai.app.name=\"$service_filter$\" gen_ai.request.model=\"$model_filter$\" ((`exclude_scoring_sourcetypes`) OR sourcetype=\"ai_cim:prompt_injection:ml_scoring\" OR (sourcetype=\"genai_scoring\" genai_scoring_pipeline=\"prompt_injection\")) | eval detector=case(sourcetype==\"ai_cim:prompt_injection:ml_scoring\",\"ML model\", sourcetype==\"genai_scoring\",\"GenAI judge\"), is_prompt=if(isnull(detector), 1, 0) | eval pid=coalesce('gen_ai.event.id', 'gen_ai.request.id', if(is_prompt=1, splunk_server.\":\"._cd, null())) | eval ad_hit=if(is_prompt=1 AND 'gen_ai.policy.blocked'==\"true\" AND isnotnull(mvfind('gen_ai.safety.categories', \"(?i)prompt.?injection\")), 1, 0), ml_hit=if(detector==\"ML model\" AND 'gen_ai.prompt_injection.ml_detected'==\"true\", 1, 0), gj_hit=if(detector==\"GenAI judge\" AND 'gen_ai.prompt_injection.genai_detected'==\"true\", 1, 0) | eval ad_cats=if(ad_hit=1, mvjoin('gen_ai.safety.categories', \" | \"), null()) | rex field=ad_cats max_match=0 \"\\((?<ad_rules>[^)]+)\\)\" | eval ad_rules=split(mvjoin(ad_rules, \",\"), \",\") | eval ad_rules=mvdedup(mvmap(ad_rules, \"AI Defense: \".trim(ad_rules))) | eval technique=case(ml_hit=1, 'gen_ai.prompt_injection.technique', gj_hit=1, coalesce('gen_ai.prompt_injection.types{}', 'gen_ai.prompt_injection.types', \"unknown\"), ad_hit=1, coalesce(ad_rules, \"AI Defense: Prompt Injection\")) | eval hit_risk=case(ml_hit=1 OR gj_hit=1, tonumber('gen_ai.prompt_injection.risk_score'), ad_hit=1, if(tonumber(risk_score)>1, tonumber(risk_score)/100, tonumber(risk_score))) | eval sev=case(ml_hit=1, 'gen_ai.prompt_injection.severity', gj_hit=1, case(hit_risk>0.9,\"critical\", hit_risk>0.7,\"high\", hit_risk>0.5,\"medium\", hit_risk>0.3,\"low\", 1=1,\"none\"), ad_hit=1, \"high\"), conf=if(ml_hit=1 OR gj_hit=1, 'gen_ai.prompt_injection.confidence', null()) | eval sev_rank=case(sev==\"critical\",4, sev==\"high\",3, sev==\"medium\",2, sev==\"low\",1, isnotnull(sev),0), conf_rank=case(conf==\"very_high\",4, conf==\"high\",3, conf==\"medium\",2, conf==\"low\",1, conf==\"very_low\",0) | stats min(_time) as _time, max(is_prompt) as is_prompt, max(ad_hit) as ad_hit, max(ml_hit) as ml_hit, max(gj_hit) as gj_hit, max(sev_rank) as sev_rank, max(conf_rank) as conf_rank, max(hit_risk) as risk, values(technique) as Technique, values(gen_ai.request.id) as Request_ID, values(gen_ai.session.id) as session, values(client.address) as src, values(gen_ai.app.name) as Service, values(gen_ai.request.model) as Model by pid | where is_prompt=1 | eval detected=if(ad_hit+ml_hit+gj_hit>0, 1, 0) | appendpipe [ bin _time span=1h | stats count as prompts, sum(detected) as detected_prompts by _time | eval clean_prompts=prompts-detected_prompts, row=\"hour\" ] | where row==\"hour\" OR detected=1 | eval row=coalesce(row, \"prompt\"), src=if(row==\"prompt\", coalesce(src, \"unknown\"), null()) | eval Severity=mvindex(split(\"none,low,medium,high,critical\", \",\"), sev_rank), Confidence=mvindex(split(\"very_low,low,medium,high,very_high\", \",\"), conf_rank), Risk_Score=round(risk, 2), Detectors=mvappend(if(ad_hit=1, \"AI Defense\", null()), if(ml_hit=1, \"ML model\", null()), if(gj_hit=1, \"GenAI judge\", null())) | fields _time, row, prompts, detected_prompts, clean_prompts, Request_ID, session, src, Service, Model, Severity, Confidence, Technique, Risk_Score, Detectors",
                "queryParameters": {
                    "earliest": "$time.earliest$",
                    "latest": "$time.latest$"
                }
            },
            "type": "ds.search"
        },
        "ds_total_scanned": {
            "options": {
                "extend": "ds_pi_base",
                "query": "| where row=\"hour\" | stats sum(prompts) as total_scanned | eval total_scanned=coalesce(total_scanned, 0)"
            },
            "type": "ds.chain"
        },
        "ds_injections_detected": {
            "options": {
                "extend": "ds_pi_base",
                "query": "| where row=\"prompt\" | stats count as injections_detected"
            },
            "type": "ds.chain"
        },
        "ds_critical_severity": {
            "options": {
                "extend": "ds_pi_base",
                "query": "| where row=\"prompt\" AND Severity=\"critical\" | stats count as critical_count"
            },
            "type": "ds.chain"
        },
        "ds_high_severity": {
            "options": {
                "extend": "ds_pi_base",
                "query": "| where row=\"prompt\" AND Severity=\"high\" | stats count as high_count"
            },
            "type": "ds.chain"
        },
        "ds_detection_rate": {
            "options": {
                "extend": "ds_pi_base",
                "query": "| where row=\"hour\" | stats sum(prompts) as scanned, sum(detected_prompts) as detected | eval detection_rate=if(scanned>0, round(detected/scanned*100, 1), 0) | fields detection_rate"
            },
            "type": "ds.chain"
        },
        "ds_detection_trend": {
            "options": {
                "extend": "ds_pi_base",
                "query": "| where row=\"hour\" | timechart span=1h sum(detected_prompts) as injections_detected, sum(clean_prompts) as clean_prompts | fillnull value=0 injections_detected clean_prompts"
            },
            "type": "ds.chain"
        },
        "ds_technique_distribution": {
            "options": {
                "extend": "ds_pi_base",
                "query": "| where row=\"prompt\" | stats count as Count by Technique | sort -Count"
            },
            "type": "ds.chain"
        },
        "ds_severity_distribution": {
            "options": {
                "extend": "ds_pi_base",
                "query": "| where row=\"prompt\" | stats count by Severity"
            },
            "type": "ds.chain"
        },
        "ds_confidence_distribution": {
            "options": {
                "extend": "ds_pi_base",
                "query": "| where row=\"prompt\" AND isnotnull(Confidence) | stats count by Confidence"
            },
            "type": "ds.chain"
        },
        "ds_top_sources": {
            "options": {
                "extend": "ds_pi_base",
                "query": "| where row=\"prompt\" | stats count as Injection_Count, dc(session) as Sessions, values(Technique) as Techniques, values(Detectors) as Detectors by src | rename src as Source_IP | sort -Injection_Count | head 10"
            },
            "type": "ds.chain"
        },
        "ds_recent_detections": {
            "options": {
                "extend": "ds_pi_base",
                "query": "| where row=\"prompt\" | sort 25 -_time | eval Timestamp=strftime(_time, \"%Y-%m-%d %H:%M:%S\") | table Request_ID, Timestamp, Detectors, Service, Model, Severity, Technique, Confidence, Risk_Score"
            },
            "type": "ds.chain"
        }
    },
    "layout": {
        "globalInputs": [
            "input_time",
            "input_service",
            "input_model"
        ],
        "options": {
            "showTitleAndDescription": true,
            "height": 1400,
            "width": 1440
        },
        "type": "grid",
        "structure": [
            {
                "item": "viz_header_prompt_injection",
                "position": {
                    "h": 50,
                    "w": 1440,
                    "x": 0,
                    "y": 0
                },
                "type": "block"
            },
            {
                "item": "viz_total_scanned",
                "position": {
                    "h": 120,
                    "w": 288,
                    "x": 0,
                    "y": 50
                },
                "type": "block"
            },
            {
                "item": "viz_injections_detected",
                "position": {
                    "h": 120,
                    "w": 288,
                    "x": 288,
                    "y": 50
                },
                "type": "block"
            },
            {
                "item": "viz_critical_severity",
                "position": {
                    "h": 120,
                    "w": 288,
                    "x": 576,
                    "y": 50
                },
                "type": "block"
            },
            {
                "item": "viz_high_severity",
                "position": {
                    "h": 120,
                    "w": 288,
                    "x": 864,
                    "y": 50
                },
                "type": "block"
            },
            {
                "item": "viz_detection_rate",
                "position": {
                    "h": 120,
                    "w": 288,
                    "x": 1152,
                    "y": 50
                },
                "type": "block"
            },
            {
                "item": "viz_detection_trend",
                "position": {
                    "h": 280,
                    "w": 720,
                    "x": 0,
                    "y": 170
                },
                "type": "block"
            },
            {
                "item": "viz_technique_distribution",
                "position": {
                    "h": 280,
                    "w": 720,
                    "x": 720,
                    "y": 170
                },
                "type": "block"
            },
            {
                "item": "viz_severity_distribution",
                "position": {
                    "h": 280,
                    "w": 720,
                    "x": 0,
                    "y": 450
                },
                "type": "block"
            },
            {
                "item": "viz_confidence_distribution",
                "position": {
                    "h": 280,
                    "w": 720,
                    "x": 720,
                    "y": 450
                },
                "type": "block"
            },
            {
                "item": "viz_top_sources",
                "position": {
                    "h": 280,
                    "w": 720,
                    "x": 0,
                    "y": 730
                },
                "type": "block"
            },
            {
                "item": "viz_recent_detections",
                "position": {
                    "h": 350,
                    "w": 1440,
                    "x": 0,
                    "y": 1010
                },
                "type": "block"
            }
        ]
    }
}
